import re
from pathlib import Path
from urllib.parse import unquote
root=Path(".").resolve()
bad=[]
patterns=[re.compile(r"!?(?:\\\\[[^\\\\]]*\\\\])\\\\(([^)]+)\\\\)"), re.compile(r"^\\\\[[^\\\\]]+\\\\]:\\\\s+(\\\\S+)", re.M)]
for p in root.rglob("*.md"):
    rel=p.relative_to(root)
    if any(x in rel.parts for x in (".git","dist","node_modules","target")):
        continue
    text=p.read_text(encoding="utf-8")
    targets=[]
    for pattern in patterns:
        targets.extend(m.group(1).strip() for m in pattern.finditer(text))
    for raw in targets:
        target=raw[1:-1] if raw.startswith("<") and raw.endswith(">") else raw.split()[0]
        target=unquote(target.split("#",1)[0])
        if not target or target.startswith(("http://","https://","mailto:","app://","/")):
            continue
        resolved=(p.parent/target).resolve()
        try:
            resolved.relative_to(root)
        except ValueError:
            bad.append((str(rel),raw,"outside repository"))
            continue
        if not resolved.exists():
            bad.append((str(rel),raw,"missing"))
for item in bad:
    print(" | ".join(item))
raise SystemExit(bool(bad))
`;
